const __vite__css = "/* Design tokens -------------------------------------------------------------
   One palette, one type scale, one spacing rhythm. Light and dark share the
   same semantic names so components never hard-code a colour. */

:root {
  --bg: #f6f6f3;
  --surface: #ffffff;
  --surface-2: #f0f0ec;
  --border: #e0e0d8;
  --border-strong: #cfcfc4;
  --text: #1c1e22;
  --muted: #61656e;
  --accent: #0f8a7e;
  --accent-weak: #dbeeeb;
  --pass: #12855f;
  --partial: #b7791f;
  --fail: #c0392b;
  --pass-weak: #dcefe6;
  --partial-weak: #f6ecd6;
  --fail-weak: #f5dfdc;

  --radius: 10px;
  --radius-sm: 6px;
  --gap: 16px;
  --gap-sm: 8px;

  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SF Mono", "Menlo", monospace;

  --shadow: 0 1px 2px rgba(20, 22, 28, 0.06), 0 2px 8px rgba(20, 22, 28, 0.04);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #0f1115;
    --surface: #171a21;
    --surface-2: #1e222b;
    --border: #2a2f3a;
    --border-strong: #3a4150;
    --text: #e6e8ec;
    --muted: #9aa3b2;
    --accent: #2dd4bf;
    --accent-weak: #143a37;
    --pass: #34d399;
    --partial: #f0b64b;
    --fail: #f87171;
    --pass-weak: #16362b;
    --partial-weak: #3a2f18;
    --fail-weak: #3a2020;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 2px 10px rgba(0, 0, 0, 0.3);
  }
}

:root[data-theme="dark"] {
  --bg: #0f1115;
  --surface: #171a21;
  --surface-2: #1e222b;
  --border: #2a2f3a;
  --border-strong: #3a4150;
  --text: #e6e8ec;
  --muted: #9aa3b2;
  --accent: #2dd4bf;
  --accent-weak: #143a37;
  --pass: #34d399;
  --partial: #f0b64b;
  --fail: #f87171;
  --pass-weak: #16362b;
  --partial-weak: #3a2f18;
  --fail-weak: #3a2020;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 2px 10px rgba(0, 0, 0, 0.3);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0;
}

button {
  font-family: inherit;
  font-size: inherit;
  cursor: pointer;
}

/* App shell ----------------------------------------------------------------- */

.shell {
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.topbar {
  display: flex;
  align-items: center;
  gap: var(--gap);
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar__brand {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.topbar__title {
  font-size: 17px;
}

.topbar__subtitle {
  color: var(--muted);
  font-size: 13px;
}

.topbar__spacer {
  flex: 1;
}

.tabs {
  display: flex;
  gap: 4px;
}

.tab {
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-weight: 500;
}

.tab:hover {
  color: var(--text);
  background: var(--surface-2);
}

.tab--active {
  color: var(--text);
  background: var(--surface-2);
  border-color: var(--border);
}

.icon-button {
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.icon-button:hover {
  color: var(--text);
}

.content {
  flex: 1;
  padding: 24px;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.banner {
  border: 1px solid var(--fail);
  background: var(--fail-weak);
  color: var(--text);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  margin-bottom: var(--gap);
}

/* Layout helpers ------------------------------------------------------------ */

.split {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: var(--gap);
  align-items: start;
}

@media (max-width: 900px) {
  .split {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
}

.card + .card {
  margin-top: var(--gap);
}

.card__title {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin-bottom: 12px;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--gap-sm);
}

.row {
  display: flex;
  gap: var(--gap-sm);
  align-items: center;
}

/* Form controls ------------------------------------------------------------- */

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.field__label {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}

.field__hint {
  font-size: 12px;
  color: var(--muted);
}

input[type="text"],
input[type="number"],
select,
textarea {
  font-family: inherit;
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  width: 100%;
}

textarea {
  font-family: var(--font-mono);
  font-size: 13px;
  resize: vertical;
  min-height: 96px;
}

input:focus,
select:focus,
textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
  border-color: var(--accent);
}

input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
}

.btn {
  border: 1px solid var(--border-strong);
  background: var(--surface);
  color: var(--text);
  padding: 9px 16px;
  border-radius: var(--radius-sm);
  font-weight: 600;
}

.btn:hover:not(:disabled) {
  background: var(--surface-2);
}

.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #06201d;
}

.btn--primary:hover:not(:disabled) {
  filter: brightness(1.06);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Checkable list of mechanisms --------------------------------------------- */

.checklist {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tier-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin: 10px 0 4px;
}

.check {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
}

.check:hover {
  background: var(--surface-2);
}

.check--on {
  border-color: var(--border);
  background: var(--surface-2);
}

.check--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.check input {
  margin-top: 3px;
  accent-color: var(--accent);
}

.check__label {
  font-weight: 500;
}

.check__desc {
  font-size: 12px;
  color: var(--muted);
}

/* Score display ------------------------------------------------------------- */

.scorebar {
  height: 8px;
  border-radius: 999px;
  background: var(--surface-2);
  overflow: hidden;
}

.scorebar__fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.35s ease;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  border: 1px solid var(--border);
}

.chip--pass {
  background: var(--pass-weak);
  color: var(--pass);
  border-color: transparent;
}

.chip--fail {
  background: var(--fail-weak);
  color: var(--fail);
  border-color: transparent;
}

.chip--partial {
  background: var(--partial-weak);
  color: var(--partial);
  border-color: transparent;
}

.chip--neutral {
  background: var(--surface-2);
  color: var(--muted);
}

.score-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  background: var(--surface);
}

.score-card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-sm);
  margin-bottom: 10px;
}

.score-card__method {
  font-weight: 600;
}

.score-card__value {
  font-family: var(--font-mono);
  font-size: 20px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.score-card__detail {
  font-size: 12px;
  color: var(--muted);
  margin-top: 8px;
  white-space: pre-wrap;
  word-break: break-word;
}

.dims {
  display: grid;
  grid-template-columns: 88px 1fr 34px;
  gap: 6px 10px;
  align-items: center;
  margin-top: 10px;
}

.dims__name {
  font-size: 12px;
  color: var(--muted);
}

.dims__value {
  font-family: var(--font-mono);
  font-size: 12px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--gap);
}

.response {
  font-family: var(--font-mono);
  font-size: 13px;
  white-space: pre-wrap;
  word-break: break-word;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 12px;
  max-height: 360px;
  overflow: auto;
}

.meta-line {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 12px;
  color: var(--muted);
  margin-top: 8px;
  font-variant-numeric: tabular-nums;
}

/* Matrix -------------------------------------------------------------------- */

.matrix {
  overflow-x: auto;
}

.matrix table {
  border-collapse: collapse;
  width: 100%;
}

.matrix th,
.matrix td {
  border: 1px solid var(--border);
  padding: 10px;
  text-align: left;
  vertical-align: top;
}

.matrix th {
  background: var(--surface-2);
  font-size: 13px;
  position: sticky;
  top: 0;
}

.matrix td.case {
  font-weight: 500;
  background: var(--surface);
}

.cell-scores {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 150px;
}

.progress {
  height: 6px;
  border-radius: 999px;
  background: var(--surface-2);
  overflow: hidden;
  margin-top: 6px;
}

.progress__fill {
  height: 100%;
  background: var(--accent);
  transition: width 0.3s ease;
}

/* Verdict ------------------------------------------------------------------- */

.verdict {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 999px;
}

.verdict--reliable {
  background: var(--pass-weak);
  color: var(--pass);
}

.verdict--questionable {
  background: var(--partial-weak);
  color: var(--partial);
}

.verdict--unreliable {
  background: var(--fail-weak);
  color: var(--fail);
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: var(--gap);
}

.metric {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
}

.metric__value {
  font-family: var(--font-mono);
  font-size: 24px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.metric__label {
  font-size: 12px;
  color: var(--muted);
}

/* Misc ---------------------------------------------------------------------- */

.muted {
  color: var(--muted);
}

.mono {
  font-family: var(--font-mono);
}

.empty {
  color: var(--muted);
  text-align: center;
  padding: 48px 16px;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius);
}

.spinner {
  width: 16px;
  height: 16px;
  border: 2px solid var(--border-strong);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  display: inline-block;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
